import java.util.*;

public class Solution {
    public int[] restoreArray(int[][] adjacentPairs) {
        int n = adjacentPairs.length + 1;
        Map<Integer, List<Integer>> adj = new HashMap<>(n);
        for (int[] p : adjacentPairs) {
            int a = p[0], b = p[1];
            adj.computeIfAbsent(a, k -> new ArrayList<>()).add(b);
            adj.computeIfAbsent(b, k -> new ArrayList<>()).add(a);
        }
        int start = 0;
        for (Map.Entry<Integer, List<Integer>> e : adj.entrySet()) {
            if (e.getValue().size() == 1) {
                start = e.getKey();
                break;
            }
        }
        int[] res = new int[n];
        res[0] = start;
        if (n == 1) return res; // not possible per constraints, but safe
        res[1] = adj.get(start).get(0);
        for (int i = 2; i < n; ++i) {
            List<Integer> neighbors = adj.get(res[i - 1]);
            int a = neighbors.get(0);
            int b = neighbors.size() > 1 ? neighbors.get(1) : Integer.MIN_VALUE;
            res[i] = (a != res[i - 2]) ? a : b;
        }
        return res;
    }
}

